import java.io.*;
import java.util.*;

public class Main {
    static final PrintWriter writer = new PrintWriter(System.out);
    static final FastReader reader = new FastReader();

    public static void main(String[] args) {
        int testCount = 1;
        for (int i = 0; i < testCount; i++) {
            process();
        }
        writer.flush();
    }

    public static void process() {
        int totalPoints = readInt();
        double probabilityThreshold = readDouble();

        int low = 0;
        int high = totalPoints - 1;
        while (low < high) {
            int midPoint = (low + high) / 2;
            double prob = calculateProbability(midPoint, totalPoints);
            if (prob >= probabilityThreshold) {
                high = midPoint;
            } else {
                low = midPoint + 1;
            }
        }
        writer.println(low);
    }

    private static double calculateProbability(int m, int n) {
        long totalComb = choose(n, 3);
        double sum = 0.0;
        sum += (double) choose(m, 3);
        sum += (double) (choose(m, 2) * choose(n - m, 1));
        sum += 0.5 * (choose(m, 1) * choose(n - m, 2));
        return sum / totalComb;
    }

    private static long choose(int n, int c) {
        if (c > n) return 0;
        if (c == n) return 1;
        long res = 1;
        for (int i = 0; i < c; i++) {
            res *= (n - i);
        }
        for (int i = 1; i <= c; i++) {
            res /= i;
        }
        return res;
    }

    static int readInt() {
        return reader.nextInt();
    }

    static double readDouble() {
        return reader.nextDouble();
    }
}
